import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  extractDocumentText,
  kindFor,
  MAX_EXTRACTED_BYTES,
  MAX_UPLOAD_BYTES,
} from "@/lib/import/extract";
import { USER_CONTENT_BUDGET_BYTES } from "@/lib/text/budget";

/**
 * Text out of an uploaded file. The fixtures are generated by
 * `scripts/make-import-fixtures.ts`, so nothing in the repository came
 * from anyone's real project.
 */

const LINE_1 = "Aureon import fixture.";
const LINE_2 = "Sellers list handmade items and buyers check out with Stripe.";
const LINE_3 = "Budget is 40,000 dollars over eight weeks.";

function fixture(name: string): Uint8Array {
  return new Uint8Array(readFileSync(`tests/fixtures/import/${name}`));
}

function textFile(content: string): Uint8Array {
  return new TextEncoder().encode(content);
}

describe("what kind of file is this", () => {
  it.each([
    ["brief.txt", "text/plain", "txt"],
    ["brief.md", "text/markdown", "md"],
    ["brief.pdf", "application/pdf", "pdf"],
    [
      "brief.docx",
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      "docx",
    ],
  ])("%s is %s", (name, mime, expected) => {
    expect(kindFor(name, mime)).toBe(expected);
  });

  it("trusts the extension over a browser's guess", () => {
    // Browsers routinely send application/octet-stream for .md.
    expect(kindFor("brief.md", "application/octet-stream")).toBe("md");
  });

  it("falls back to the declared type when there is no extension", () => {
    expect(kindFor("brief", "application/pdf")).toBe("pdf");
  });

  it("does not guess at anything else", () => {
    expect(kindFor("brief.pages", "application/x-iwork-pages-sffpages")).toBeNull();
    expect(kindFor("brief.doc", "application/msword")).toBeNull();
    expect(kindFor("archive.zip", "application/zip")).toBeNull();
  });
});

describe("a PDF", () => {
  it("comes out as the lines it was written with", async () => {
    const result = await extractDocumentText({
      fileName: "requirements.pdf",
      mimeType: "application/pdf",
      bytes: fixture("requirements.pdf"),
    });

    expect(result.kind).toBe("pdf");
    expect(result.pages).toBe(1);
    expect(result.text).toContain(LINE_1);
    expect(result.text).toContain(LINE_2);
    expect(result.truncated).toBe(false);
    expect(result.overBudget).toBe(false);
    expect(result.bytes).toBeGreaterThan(0);
  });
});

describe("a DOCX", () => {
  it("comes out as its paragraphs, without the styling", async () => {
    const result = await extractDocumentText({
      fileName: "requirements.docx",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      bytes: fixture("requirements.docx"),
    });

    expect(result.kind).toBe("docx");
    expect(result.pages).toBeNull();
    expect(result.text).toContain(LINE_1);
    expect(result.text).toContain(LINE_2);
    expect(result.text).toContain(LINE_3);
    expect(result.text).not.toContain("<w:p");
  });
});

describe("plain text and markdown", () => {
  it("keeps markdown as it was written", async () => {
    const result = await extractDocumentText({
      fileName: "requirements.md",
      mimeType: "text/markdown",
      bytes: fixture("requirements.md"),
    });

    expect(result.kind).toBe("md");
    expect(result.text).toContain(`# ${LINE_1}`);
    expect(result.text).toContain(LINE_3);
  });

  it("tidies the page layout out of it", async () => {
    const result = await extractDocumentText({
      fileName: "brief.txt",
      mimeType: "text/plain",
      bytes: textFile("  Spaced    out\r\n\r\n\r\n\r\nand    hyphen­ated  \n"),
    });

    expect(result.text).toBe("Spaced out\n\nand hyphenated");
  });
});

describe("what it refuses", () => {
  it("a file type it cannot read", async () => {
    await expect(
      extractDocumentText({
        fileName: "brief.doc",
        mimeType: "application/msword",
        bytes: textFile("anything"),
      }),
    ).rejects.toThrow(/\.txt, \.md, \.pdf and \.docx/);
  });

  it("an empty file", async () => {
    await expect(
      extractDocumentText({
        fileName: "brief.txt",
        mimeType: "text/plain",
        bytes: new Uint8Array(0),
      }),
    ).rejects.toThrow(/empty/i);
  });

  it("a file with nothing readable in it", async () => {
    await expect(
      extractDocumentText({
        fileName: "brief.txt",
        mimeType: "text/plain",
        bytes: textFile("   \n\n  \t "),
      }),
    ).rejects.toThrow(/No text/i);
  });

  it("anything over 5 MB", async () => {
    await expect(
      extractDocumentText({
        fileName: "brief.txt",
        mimeType: "text/plain",
        bytes: new Uint8Array(MAX_UPLOAD_BYTES + 1),
      }),
    ).rejects.toThrow(/limit is 5 MB/);
  });
});

describe("the byte budget", () => {
  it("says so when the text does not fit, and hands back what it can", async () => {
    const long = "Sellers list handmade items. ".repeat(6_000);
    const result = await extractDocumentText({
      fileName: "long.txt",
      mimeType: "text/plain",
      bytes: textFile(long),
    });

    expect(result.bytes).toBeGreaterThan(USER_CONTENT_BUDGET_BYTES);
    expect(result.overBudget).toBe(true);
    expect(result.truncated).toBe(true);
    expect(new TextEncoder().encode(result.text).length).toBeLessThanOrEqual(
      MAX_EXTRACTED_BYTES,
    );
  });

  it("cuts on a character, not in the middle of one", async () => {
    // Four bytes each, so a naive byte slice would split one.
    const emoji = "🙂".repeat(40_000);
    const result = await extractDocumentText({
      fileName: "emoji.txt",
      mimeType: "text/plain",
      bytes: textFile(emoji),
    });

    expect(result.truncated).toBe(true);
    expect(result.text).not.toContain("�");
    expect([...result.text].every((ch) => ch === "🙂")).toBe(true);
  });

  it("is happy with a brief that fits", async () => {
    const result = await extractDocumentText({
      fileName: "brief.txt",
      mimeType: "text/plain",
      bytes: textFile("A marketplace for handmade crafts."),
    });

    expect(result.overBudget).toBe(false);
    expect(result.truncated).toBe(false);
  });
});
